var a = [9, 4, 7, 1, 8, 2];
for (var i = 1; i < a.length; i++) {
  var key = a[i];
  var j = i - 1;
  while (j >= 0 && a[j] > key) {
    a[j + 1] = a[j];
    j--;
  }
  a[j + 1] = key;
}
console.log(a);
